import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Plan - FR 3.5.3","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-3-request-media-package/plan.md","filePath":"feature/media-package-campaign/3-5-3-request-media-package/plan.md"}'),o={name:"feature/media-package-campaign/3-5-3-request-media-package/plan.md"};function r(s,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="plan-fr-3-5-3" tabindex="-1">Plan - FR 3.5.3 <a class="header-anchor" href="#plan-fr-3-5-3" aria-label="Permalink to &quot;Plan - FR 3.5.3&quot;">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Implement E50-04 negotiation requests/counter-offers without replacing the selected package.</p><h2 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h2><ol><li>Add <code>terms_version</code> plus append-only negotiation-event migration and V2 init update.</li><li>Implement request-change, counter-offer, and history read endpoints with role/state checks.</li><li>In the same transaction, update current terms, increment version, and invalidate both approvals.</li><li>Test multi-round immutable history and approval invalidation.</li></ol><h2 id="phase-5-implementation-detail" tabindex="-1">Phase 5 implementation detail <a class="header-anchor" href="#phase-5-implementation-detail" aria-label="Permalink to &quot;Phase 5 implementation detail&quot;">​</a></h2><ul><li>Add new SQL migration and matching init table with UUID PK, selection FK CASCADE, terms_version, action/actor_role/actor_id/note/terms_snapshot/created_at, unique (workspace_media_package_id,terms_version), version-desc paging index. Trigger blocks direct mutations; parent cascade deletion remains compatible.</li><li>Backfill BASELINE only if non-DRAFT; insert-if-no-events, lock selections during maintenance migration. Do not mutate selection data.</li><li>Immutable JPA entity + insert-only EntityManager store (no public save/delete repository), pageable read repository. Writer must join selection JPA transaction. Capture baseline before replacing terms; append after count/version/reset changes.</li><li>Add history scoped service/controller and API DTOs. Reuse Workspace permission service but explicitly restrict history roles. No dependency on Mongo.</li><li>Extend negotiation DTO with required expectedTermsVersion + optional note; use explicit-version convenience constructors and require HTTP validation. Approve gets validated body; service checks version under row lock even when approved.</li><li>DRAFT package replacement advances termsVersion and resets approvals/count, never reuses a previous version. No baseline created until first negotiation.</li><li>Web typed client, modal note + fixed version captured when editing starts; approve always sends displayed version. 409 preserves input, prompts close/reload.</li><li>Add feature hook/components, reuse PackageTermsDiff, parallel locales <code>src/i18n/locales/{vi,en}/mediaPackage.json</code>; no new global providers/styles.</li><li>Regression Package/Campaign/Request unit tests + isolated PostgreSQL transaction, immutability/rerun/schema tests and browser fixture. Shared writes/migrations and live Gateway smoke remain operator steps. No seed accounts, no commit/push.</li></ul>',7)])])}const h=a(o,[["render",r]]);export{u as __pageData,h as default};
